"""
Runs Stranded II (tests/stranded2) in a loaded map for a number of frames and prints the milliseconds per frame, the
draw calls and the triangles.

    python3 tools/benchmark_stranded2.py [path to blitzcc] [map ...]

A map is the name of a file in mods/Stranded II/maps (such as "Survival Guide"), or "random" for a random island.
BENCH_FRAMES is how many frames are timed (default 300), BENCH_W and BENCH_H the size of the window (default 800x600),
BENCH_SHOT=<file> saves the last frame as a picture, BENCH_BLITZCC_ARGS are more arguments for blitzcc (such as -g), and
BENCH_KEEP=<directory> keeps a copy of the game and the program that was built, for profiling (BLITZ_SAMPLE=<file>). The copy of the game that is run starts in the map at once
and does not wait for 50 frames per second, the rest is the game as it is. On Windows run it from the CI build.

Without a display it runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU rasterizing
and only good for comparing one build with another.
"""
import os
import re
import shutil
import subprocess
import sys
import tempfile

BENCH = r'''
Global bench_t0
Function bench_start()
	m_section=Csection_game_sp
	m_menu=0
	set_debug_testmap=0
	If GetEnv$("BENCH_MAP")="random" Then
		randommapcreate()
	Else
		load_map("maps\"+GetEnv$("BENCH_MAP")+".s2","")
	EndIf
	bench_t0=MilliSecs()
End Function

; Closes the menus that the map opens, then walks forward and sideways while the mouse turns the camera around, so that
; the game is not paused and the view changes like it does when somebody plays.
Function bench_input()
	If m_menu>0 And m_menu<Cmenu_if_movie Then m_menu=0
	in_mxs#=40.0*Sin(bench_frame*2.0)
	in_mys#=3.0*Sin(bench_frame*1.3)
	; Forward, back and sideways in turn, so that it stays about where it started.
	Local phase=bench_frame Mod 400
	in_keydown(Ckey_forward)=(phase<100)
	in_keydown(Ckey_backward)=(phase>=200 And phase<300)
	in_keydown(Ckey_right)=(phase>=100 And phase<150)
	in_keydown(Ckey_left)=(phase>=300 And phase<350)
End Function

Function bench_end()
	Local ms=MilliSecs()-bench_t0
	Local frames=Int(GetEnv$("BENCH_FRAMES"))
	If GetEnv$("BENCH_SHOT")<>"" Then SaveBuffer(BackBuffer(),GetEnv$("BENCH_SHOT"))
	DebugLog "ms_per_frame="+(Float(ms)/Float(frames))+" draws="+Stats3D(1000)+" pipelines="+Stats3D(1001)+" textures="+Stats3D(1002)+" buffers="+Stats3D(1003)+" tris="+TrisRendered()
	End
End Function
'''


def prepare(root, directory):
    game = os.path.join(directory, "stranded2")
    shutil.copytree(os.path.join(root, "tests", "stranded2"), game)
    path = os.path.join(game, "StrandedII.bb")
    with open(path, "rb") as f:
        text = f.read().decode("latin-1").replace("\r\n", "\n")
    # Start in the map instead of the menu, stop after the frames, and don't wait for 50 frames per second.
    text = text.replace("menu_start()\n\nWhile Not m_performquit", "bench_start()\n\nWhile Not m_performquit", 1)
    text = text.replace("\tgframe=gframe+1\n", "\tgframe=gframe+1\n\tbench_frame=bench_frame+1\n\tIf bench_frame=Int(GetEnv$(\"BENCH_FRAMES\")) Then bench_end()\n", 1)
    text = text.replace("\tFlip\n\t\nWend", "\tFlip False\n\t\nWend", 1) # Without waiting for the display, which would cap the frames.
    text = text.replace("Const Cversion$", "Global bench_frame\nConst Cversion$", 1)
    with open(path, "wb") as f:
        f.write((text + BENCH).encode("latin-1"))
    path = os.path.join(game, "includes", "input.bb")
    with open(path, "rb") as f:
        text = f.read().decode("latin-1").replace("\r\n", "\n")
    with open(path, "wb") as f:
        f.write(text.replace("\t;Statefx\n", "\tbench_input()\n\t;Statefx\n", 1).encode("latin-1"))
    fps = os.path.join(game, "includes", "load_fps.bb")
    with open(fps, "rb") as f:
        text = f.read().decode("latin-1")
    with open(fps, "wb") as f:
        f.write(text.replace("Global looplimit=20", "Global looplimit=0").encode("latin-1"))
    # The graphics modes of a window system that is made for the test may not have the size of the game.
    setup = os.path.join(game, "includes", "load_setup.bb")
    with open(setup, "rb") as f:
        text = f.read().decode("latin-1")
    text = text.replace("If GfxMode3DExists(set_scrx,set_scry,set_scrbit) Then", "If GetEnv$(\"BENCH_W\")<>\"\" Then set_scrx=Int(GetEnv$(\"BENCH_W\")):set_scry=Int(GetEnv$(\"BENCH_H\"))\nIf GetEnv$(\"BENCH_W\")<>\"\" Or GfxMode3DExists(set_scrx,set_scry,set_scrbit) Then", 1)
    with open(setup, "wb") as f:
        f.write(text.encode("latin-1"))
    return game


def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    args = sys.argv[1:]
    compiler = args.pop(0) if args and os.path.isfile(args[0]) else os.path.join(root, "build", "code_compiler", "blitzcc")
    maps = args or ["Survival Guide", "random"]
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or os.name == "nt" else ["xvfb-run", "-a", "-s", "-screen 0 800x600x24"]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")
    with tempfile.TemporaryDirectory() as directory:
        game = prepare(root, directory)
        program = os.path.join(game, "stranded2_bench")
        subprocess.run([compiler, "-q"] + os.environ.get("BENCH_BLITZCC_ARGS", "").split() + [os.path.join(game, "StrandedII.bb"), "-o", program], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        env = dict(os.environ, BENCH_FRAMES=os.environ.get("BENCH_FRAMES", "300"), BENCH_W=os.environ.get("BENCH_W", "800"), BENCH_H=os.environ.get("BENCH_H", "600"))
        if os.environ.get("BENCH_KEEP"):
            # Keeps the program and the debug information, which is what turns the addresses of BLITZ_SAMPLE into names.
            shutil.copytree(game, os.environ["BENCH_KEEP"], dirs_exist_ok=True)
        print("%-16s %9s %7s %10s %9s %8s %10s" % ("map", "tris", "draws", "pipelines", "textures", "buffers", "ms/frame"))
        for name in maps:
            env["BENCH_MAP"] = name
            result = subprocess.run(runner + [program, "-win"], cwd=game, env=env, capture_output=True, text=True, timeout=1800)
            output = result.stdout + result.stderr
            values = dict(re.findall(r"(\w+)=([\d.]+)", output))
            if "draws" not in values:
                print("%-16s failed: %s" % (name, output.strip().splitlines()[-1] if output.strip() else "no output"))
                continue
            print("%-16s %9s %7s %10s %9s %8s %10.2f" % (name, values["tris"], values["draws"], values["pipelines"], values["textures"], values["buffers"], float(values["ms_per_frame"])))


main()
